      ('P','老 iOS 有 300ms 点击延迟。XuNay 用 touch-action: manipulation 去掉。'),
      ('H3','移动端 hover 效果残留'),
      ('P','触摸设备上 hover 会一直保持。XuNay 用 @media (hover: none) 去掉 hover 效果。'),
      ('H3','滚动穿透'),
      ('P','Modal 打开时背景还能滚。用 lockScroll() 锁住。'),
      ('Tip','用 isTouch() 检测触摸设备，比 window.innerWidth 更准。'),
