      ('Code',"const C = ctx('root')\nC.provide('a', () => {\n  C.get()   // 'a'\n  C.provide('b', () => {\n    C.get()   // 'b'\n  })\n  C.get()   // 'a'\n})",'xuy'),
      ('H2','陷阱'),
